        /* Підключення елегантного шрифту, схожого на той, що в image_0b78be.png */
        @import url('/assets/4b6c942ee3b2d8cdda9faabad0d65cf8df2e786b.css');


        .price-table {
            width: 100%;
            background-color: #fbf9f6; /* Легкий теплий відтінок фону */
            border: 1px solid #e9e3db;
            border-radius: 16px;
            overflow: hidden;
            box-shadow: 0 4px 24px rgba(0, 0, 0, 0.02);
        }

        .price-row {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 24px 32px;
            border-bottom: 1px solid #e9e3db;
            transition: background-color 0.2s ease;
        }

        .price-row:last-child {
            border-bottom: none;
        }

        .price-row:hover {
                background-color: #f6f6ee94; /* Легкий ефект при наведенні */
        }

        .service-name {
            font-family: 'Playfair Display', serif;
            font-size: 18px;
            color: #2c2724;
            font-weight: 400;
            padding-right: 20px;
        }

        .service-price {
            font-family: 'Playfair Display', serif;
            font-size: 20px;
            color: #2c2724;
            white-space: nowrap;
            font-weight: 400;
        }

        /* Адаптивність для мобільних пристроїв */
        /* Адаптивные настройки для мобильных экранов */
        @media (max-width: 600px) {
            .price-title {
                font-size: 28px;
                margin-bottom: 20px;
            }

            .price-table {
                border-radius: 16px; /* Чуть меньший радиус на мобильных */
            }

            .price-row {
                padding: 20px 24px; /* Уменьшенные внутренние отступы на смартфонах */
                gap: 16px;
                /* Выравнивание по базовой линии текста, чтобы цена визуально 
                   оставалась на уровне первой строки длинного названия */
                align-items: flex-start; 
            }

            .service-name {
                font-size: 17px;
            }

            .service-price {
                font-size: 19px;
                /* Небольшое смещение вниз для идеального выравнивания с шрифтом Cormorant */
                margin-top: 1px; 
            }
        }

