/* Основной контейнер галереи */
.masonry-gallery {
  column-count: 3;
  column-gap: 24px; /* Чуть больше "воздуха" между колонками */
  width: 100%;
  max-width: 1600px;
  margin: 0 auto;
}

/* Элемент галереи (контейнер карточки) */
.gallery-item {
  display: inline-block;
  width: 100%;
  margin-bottom: 24px;
  border-radius: 12px; /* Чуть более строгий радиус скругления */
  overflow: hidden;
  break-inside: avoid;
  text-decoration: none;

  /* Базовая едва уловимая тень для отделения от фона */
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.02); 

  /* Плавная, благородная анимация с использованием кубической кривой Безье */
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1), 
              box-shadow 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Изображение внутри */
.gallery-item img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 12px;
  object-fit: cover;

  /* Черно-белый фильтр по умолчанию */
  filter: grayscale(100%);

  /* Анимация фильтра и легкого зума */
  transition: filter 0.6s cubic-bezier(0.22, 1, 0.36, 1), 
              transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

/* --- Эффекты при наведении (Hover) --- */

.gallery-item:hover {
  /* Легкое, ненавязчивое поднятие всей карточки */
  transform: translateY(-4px); 
  /* Мягкая, объемная тень с широким радиусом размытия */
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.08);
}

.gallery-item:hover img {
  /* Возвращаем цвет */
  filter: grayscale(0%);
  /* Легкий зум изображения внутри рамки для создания глубины */
  transform: scale(1.02); 
}

/* --- Адаптивность --- */

/* Планшеты и небольшие ноутбуки */
@media (max-width: 1200px) {
  .masonry-gallery {
    column-count: 3;
    column-gap: 20px;
  }
}

/* Большие телефоны и вертикальные планшеты */
@media (max-width: 768px) {
  .masonry-gallery {
    column-count: 2;
    column-gap: 16px;
  }
  .gallery-item {
    margin-bottom: 16px;
  }

  /* На мобильных устройствах ховер работает не так хорошо, 
     можно отключить ЧБ или оставить как есть, в зависимости от задачи */
}

/* Маленькие экраны */
@media (max-width: 480px) {
  .masonry-gallery {
    column-count: 1;
  }
}

