#menut {
  position: fixed;      /* Закрепляем меню относительно окна браузера */
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;        /* Чтобы меню было поверх остальных элементов */

  /* Изначально прячем меню за пределами экрана (сдвигаем вверх на 100% его высоты) */
  transform: translateY(-100%); 

  /* Добавляем плавность появления (0.3 секунды) */
  transition: transform 0.3s ease-in-out; 
}

/* Этот класс добавляется через JavaScript */
#menut.is-sticky {
  /* Возвращаем меню на его законное место */
  transform: translateY(0); 
}

